/**
 * Object mapping (java-driver.md §5, FR-DRV-002): records, POJOs and sealed hierarchies to and
 * from {@link io.rustegon.driver.rdoc.RDocument}. Annotations ({@link
 * io.rustegon.driver.mapping.RustegonDocument}, {@code @Rgn*}) control the mapping; codecs are
 * generated by the {@code rustegon-processor} annotation processor or built at run time with
 * {@code MethodHandles} ({@link io.rustegon.driver.mapping.Mapper}). {@link
 * io.rustegon.driver.mapping.ObjectCodec}, {@link io.rustegon.driver.mapping.SealedCodec} and
 * {@link io.rustegon.driver.mapping.Values} are the building blocks of both.
 *
 * <p>In a named module, the packages of mapped types must be exported to
 * {@code io.rustegon.driver} (generated codecs) or opened to it ({@code MethodHandles} mapper).
 */
package io.rustegon.driver.mapping;
